import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# --------------------------------------------------------------------
# CUDA source implementing LayerNorm for fp16 (no affine, default eps=1e-5)
# --------------------------------------------------------------------
cuda_source = r'''
#include <torch/extension.h>
#include <ATen/ATen.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_fp16.h>
#include <cuda_runtime.h>

template <typename scalar_t>
__global__ void layer_norm_fp16_kernel(const scalar_t* __restrict__ input,
                                       scalar_t* __restrict__ output,
                                       const int N,
                                       const float eps) {
    // One block per batch element
    const int batch_idx = blockIdx.x;
    const scalar_t* in = input + batch_idx * N;
    scalar_t* out = output + batch_idx * N;

    // ----- reduction for mean and variance (fp32 accumulation) -----
    __shared__ float s_sum[256];
    __shared__ float s_sumsq[256];

    int tid = threadIdx.x;
    float sum = 0.0f;
    float sumsq = 0.0f;

    // stride over the N elements
    for (int i = tid; i < N; i += blockDim.x) {
        float val = __half2float(in[i]);   // convert fp16 -> fp32
        sum   += val;
        sumsq += val * val;
    }
    s_sum[tid]    = sum;
    s_sumsq[tid] = sumsq;
    __syncthreads();

    // parallel reduction in shared memory (blockDim.x assumed <=256 & power of two)
    for (int offset = blockDim.x / 2; offset > 0; offset >>= 1) {
        if (tid < offset) {
            s_sum[tid]    += s_sum[tid + offset];
            s_sumsq[tid] += s_sumsq[tid + offset];
        }
        __syncthreads();
    }

    const float mean = s_sum[0] / static_cast<float>(N);
    const float var  = s_sumsq[0] / static_cast<float>(N) - mean * mean;
    const float inv_std = rsqrtf(var + eps);

    __syncthreads(); // ensure mean/var are visible to all threads

    // ----- normalize -----
    for (int i = tid; i < N; i += blockDim.x) {
        float val = __half2float(in[i]);
        float norm = (val - mean) * inv_std;
        out[i] = __float2half(norm);
    }
}

// C++ wrapper called from Python
torch::Tensor layer_norm_cuda_forward(torch::Tensor input, const float eps) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(input.dtype() == torch::kHalf, "input must be float16");
    TORCH_CHECK(input.dim() >= 1, "input must have at least one dimension");

    const int64_t batch = input.size(0);
    const int64_t N = input.numel() / batch;   // product of normalized dimensions

    auto output = torch::empty_like(input);

    const int threads = 256;
    const dim3 blocks(batch);
    const dim3 threads_per_block(threads);

    AT_DISPATCH_HALF_TYPES(input.scalar_type(), "layer_norm_cuda_forward", ([&] {
        layer_norm_fp16_kernel<scalar_t><<<blocks, threads_per_block>>>(
            input.data_ptr<scalar_t>(),
            output.data_ptr<scalar_t>(),
            static_cast<int>(N),
            eps);
    }));

    // synchronize and check for errors
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        AT_ERROR("CUDA kernel failed : ", cudaGetErrorString(err));
    }
    cudaDeviceSynchronize();

    return output;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("forward", &layer_norm_cuda_forward, "LayerNorm forward (fp16, CUDA)");
}
'''

# --------------------------------------------------------------------
# Build the extension inline
# --------------------------------------------------------------------
layernorm_cuda = load_inline(
    name='layernorm_cuda',
    cpp_sources='',
    cuda_sources=cuda_source,
    functions=['forward'],
    verbose=False,
)

# --------------------------------------------------------------------
# Autograd Function that uses the compiled kernel
# --------------------------------------------------------------------
class LayerNormFunction(torch.autograd.Function):
    @staticmethod
    def forward(ctx, input, eps=1e-5):
        return layernorm_cuda.forward(input, eps)

    @staticmethod
    def backward(ctx, grad_output):
        # For brevity we delegate backward to PyTorch's autograd by
        # re‑using the forward with a tensor that requires grad.
        # This will trigger the native autograd path (inefficient but correct).
        input = ctx.saved_tensors[0]
        input.requires_grad = True
        out = layernorm_cuda.forward(input, ctx.eps)
        out.backward(grad_output)
        return input.grad, None

# --------------------------------------------------------------------
# ModelNew – drop‑in replacement for the reference Model
# --------------------------------------------------------------------
class ModelNew(nn.Module):
    """
    Same API as the reference Model but uses a custom CUDA LayerNorm kernel.
    """
    def __init__(self, normalized_shape: tuple):
        super(ModelNew, self).__init__()
        # store shape for potential future use (not needed for kernel)
        self.normalized_shape = normalized_shape
        self.eps = 1e-5

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Expect x to be fp16 CUDA tensor; cast if necessary
        if not x.is_cuda:
            raise RuntimeError("ModelNew only supports CUDA tensors")
        if x.dtype != torch.float16:
            x = x.half()
        return LayerNormFunction.apply(x, self.eps)

# --------------------------------------------------------------------
# Helper functions matching the reference script interface
# --------------------------------------------------------------------
def get_inputs():
    batch_size = 16
    features = 64
    dim1 = 256
    dim2 = 256
    x = torch.rand(batch_size, features, dim1, dim2, device='cuda', dtype=torch.float16)
    return [x]

def get_init_inputs():
    features = 64
    dim1 = 256
    dim2 = 256
    return [(features, dim1, dim2)]

# --------------------------------------------------------------------
# Example sanity check (can be removed in production)
# --------------------------------------------------------------------
if __name__ == "__main__":
    mdl = ModelNew((64, 256, 256)).cuda()
    inp = get_inputs()[0]
    out = mdl(inp)
    # Compare against PyTorch's built‑in LayerNorm for verification
    ref = torch.nn.LayerNorm((64, 256, 256)).cuda()
    ref_out = ref(inp)
    max_err = (out - ref_out).abs().max()
    print("Maximum absolute error vs PyTorch LayerNorm:", max_err.item())
